head.b:skin:
:root { --primary: #6c5ce7; --bg-body: #f8f9fa; --radius: 16px; --header-height: 60px; }
body { font-family: 'Inter', sans-serif; background: linear-gradient(135deg, #f8f9fa 0%, #dbe0e4 100%); padding-top: 95px !important; margin: 0; overflow-x: hidden; min-height: 100vh; }
.glass-panel, .modal-content { background: rgba(255, 255, 255, 0.95) !important; border: 1px solid rgba(255,255,255,0.5); box-shadow: 0 10px 40px rgba(0,0,0,0.1); }
.sticky-action-bar { position: fixed; bottom: 20px; left: 20px; right: 20px; z-index: 2000; display: flex; gap: 10px; background: rgba(255,255,255,0.9); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,0.5); padding: 8px; border-radius: 50px; box-shadow: 0 10px 30px rgba(0,0,0,0.15); }
.qty-pill { background: #f8f9fa; border-radius: 50px; display: flex; align-items: center; justify-content: space-between; width: 120px; height: 50px; padding: 0 5px; }
.qty-btn { width: 40px; height: 100%; border: none; background: transparent; font-weight: bold; font-size: 1.2rem; color: #2d3436; }
.parallax-wrapper { height: 100%; overflow-y: auto; overflow-x: hidden; position: relative; }
.sticky-img-header { position: sticky; top: 0; z-index: 0; height: 350px; display: flex; align-items: center; justify-content: center; padding: 20px; }
.sticky-img-header img { max-height: 280px; max-width: 90%; mix-blend-mode: multiply; object-fit: contain; }
.sliding-glass-sheet { position: relative; z-index: 10; background: rgba(255, 255, 255, 0.85) !important; backdrop-filter: blur(15px); -webkit-backdrop-filter: blur(15px); border-top: 1px solid rgba(255, 255, 255, 0.5); min-height: 100%; border-radius: 30px 30px 0 0; padding: 30px 25px 100px 25px; margin-top: -50px; }
.modal-dialog { background: transparent !important; margin: 10px auto; display: flex; align-items: center; justify-content: center; min-height: calc(100% - 20px); }
.modal-content { border-radius: 24px !important; border: none !important; overflow: hidden; height: auto; max-height: 85vh; width: 100%; max-width: 500px; } 
.modal-body { padding: 0 !important; height: 100%; overflow-y: auto; }
.fixed-top { background: rgba(255,255,255,0.8); backdrop-filter: blur(12px); border-bottom: 1px solid rgba(255,255,255,0.3); z-index: 1030; height: var(--header-height); top: 32px; transition: 0.3s; }
body.is-scrolled .fixed-top { top: 0 !important; }
.promo-bar { background: #2d3436; color: #fff; height: 32px; line-height: 32px; position: fixed; top: 0; width: 100%; z-index: 1040; overflow: hidden; font-size: 0.75rem; font-weight: 700; transition: transform 0.3s ease; }
body.is-scrolled .promo-bar { transform: translateY(-100%); }
.promo-content { display: inline-block; white-space: nowrap; padding-left: 100%; animation: marquee 20s linear infinite; }
@keyframes marquee { 0% { transform: translate(0, 0); } 100% { transform: translate(-100%, 0); } }
.cat-slider-container { overflow-x: auto !important; display: flex; gap: 15px; padding: 10px 15px; margin: 0 -12px; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
.cat-slider-container::-webkit-scrollbar { display: none; } 
.cat-item { flex: 0 0 auto; width: 85px; display: flex; flex-direction: column; align-items: center; }
.cat-icon { width: 55px; height: 55px; background: rgba(255,255,255,0.8); backdrop-filter: blur(5px); border-radius: 18px; display: flex; align-items: center; justify-content: center; color: var(--primary); border: 1px solid rgba(255,255,255,0.5); font-size: 1.5rem; }
.product-card { background: rgba(255,255,255,0.5); backdrop-filter: blur(10px); border-radius: var(--radius); overflow: hidden; border: 1px solid rgba(255,255,255,0.3); transition: 0.3s; position: relative; height: 100%; }
.img-box img { mix-blend-mode: multiply; transition: 0.3s; max-width: 100%; }
.action-btn { width: 35px; height: 35px; border-radius: 50%; background: rgba(255,255,255,0.8); display: flex; align-items: center; justify-content: center; transition: 0.2s; }
.module-section { display: none; opacity: 0; transform: translateY(15px); transition: all 0.4s; }
.module-section.active { display: block !important; opacity: 1; transform: translateY(0); }
.flying-img { z-index: 11000 !important; position: fixed; pointer-events: none; transition: 0.8s; object-fit: contain; background: white; border: 2px solid var(--primary); border-radius: 50%; }
.nav-btn { background: transparent; border: none; color: #2d3436; font-size: 1.25rem; position: relative; width: 40px; height: 40px; border-radius: 50%; transition: all 0.2s; display: flex; align-items: center; justify-content: center; }
.nav-btn:active { transform: scale(0.9); background: rgba(0,0,0,0.05); }
.nav-btn .badge { z-index: 10; padding: 0.35em 0.65em; font-size: 0.65rem; border: 2px solid white; }
#orderDetailModal .modal-content { height: auto !important; min-height: auto !important; background: #fff !important; backdrop-filter: none; padding: 10px; }
#orderDetailModal .modal-dialog { align-items: center; min-height: auto; }
/* --- MOBILE & APP OPTIMIZATIONS --- */

/* 1. Control Bar - Sticky & Blurry (App Feel) */
.control-bar { 
    transition: top 0.3s ease; 
    top: 60px; /* Below header */
    z-index: 1020; 
    backdrop-filter: blur(10px); 
    -webkit-backdrop-filter: blur(10px); /* Safari support */
    background: rgba(248,249,250,0.85); 
    margin-left: -12px; /* Fix Blogger/Bootstrap padding gap */
    margin-right: -12px;
    padding-left: 15px !important;
    padding-right: 15px !important;
}

body.is-scrolled .control-bar { 
    top: 0px; /* Sticks to very top when scrolling down */
    padding-top: 10px !important;
    padding-bottom: 10px !important;
    background: rgba(255,255,255,0.95);
    box-shadow: 0 4px 10px rgba(0,0,0,0.05);
}

/* 2. Input Field - Anti-Zoom for iPhone */
#catalog-search-input {
    font-size: 16px !important; /* PREVENTS IPHONE AUTO-ZOOM */
    height: 42px;
}

/* 3. Search Results - Keyboard Safe */
.search-results { 
    display: none; 
    position: absolute; 
    top: 100%; left: 10px; right: 10px; /* Slight gap from edges */
    background: white; 
    border-radius: 16px; 
    margin-top: 8px; 
    box-shadow: 0 10px 40px rgba(0,0,0,0.2); 
    z-index: 1030; 
    max-height: 50vh; /* Limits height so keyboard doesn't hide bottom items */
    overflow-y: auto; 
    -webkit-overflow-scrolling: touch; /* Smooth scroll on iOS */
    border: 1px solid rgba(0,0,0,0.05);
}

/* 4. Touch Targets */
.bi-x-circle-fill {
    font-size: 1.1rem;
    padding: 10px; /* Larger tap area */
}

/* 5. Filters - Prevent Squishing */
#stock-filter-select {
    flex-shrink: 0; /* Ensures text doesn't collapse */
    width: auto !important;
    max-width: 80px;
}

body.script:
//
const API_URL = "https://script.google.com/macros/s/AKfycbwEM-PCUyYTFH-FSZwyAezrQpwmZ1OdeVXLJoTtwk4QMmMz0_B4LhXsBKXmF4WQ9AEv/exec";
const IMG_FALLBACK = "https://placehold.co/400x400?text=No+Image";
const $ = i => document.getElementById(i);

const App = {
  State: { 
      user: null, catalog: [], cart: [], wishlist: [], tempOrders: [], 
      visibleCount: 12, adminPw: null, usePoints: false, addresses: {}, 
      qvQty: 1, pdQty: 1, lastOrder: null,
      translations: {}, config: {}, lang: localStorage.getItem('se_lang') || 'fr',
      fuse: null 
  },

  Router: {
    init: () => { window.onpopstate = () => App.Router.resolve(); App.Router.resolve(); },
    resolve: () => App.Router.go(location.hash.slice(1) || 'home', false),
    go: (id, push=true) => {

	  if(id === 'cpanel' && !App.CPanel.data.stats) { App.CPanel.login(); return; } // Hook for CPanel
  	  if(id === 'admin' && !App.State.adminPw) { App.Admin.login(); return; }

      document.querySelectorAll('.module-section').forEach(s => { s.classList.remove('active'); s.style.display='none'; });
      const m = $(id+'-module'); if(m) { m.style.display='block'; setTimeout(()=>m.classList.add('active'),10); }
      if(push) history.pushState(null, null, '#'+id); window.scrollTo(0,0);
    },
    back: () => (window.history.length > 1) ? window.history.back() : App.Router.go('home')
  },

  Utils: {
    t: (key) => { const db = App.State.translations; const ln = App.State.lang; if(db && db[key] && db[key][ln]) return db[key][ln]; return key; },
    fmt: n => (parseFloat(n)||0).toFixed(2)+' DH',
    toast: (m,t='dark') => { const b=document.createElement('div'); b.className=`toast show align-items-center text-bg-${t} border-0 position-fixed top-0 start-50 translate-middle-x mt-3 rounded-pill`; b.style.zIndex=11000; b.innerHTML=`<div class="d-flex"><div class="toast-body px-4 fw-bold">${m}</div></div>`; document.body.appendChild(b); setTimeout(()=>b.remove(),3000); },
    parseImg: u => { if(!u||u==='undefined'||u==='null') return IMG_FALLBACK; if(u.trim().startsWith('[')) { try { const p=JSON.parse(u); return p[0]||IMG_FALLBACK; } catch(e){ return IMG_FALLBACK; } } return u; },

    text: o => {
        if (!o) return "";
        if (typeof o === 'string') return o;
        if (typeof o !== 'object') return String(o); 
        const l = App.State.lang || 'fr';
        return String(o[l] || o['fr'] || o['en'] || "");
    },

    isFav: id => App.State.wishlist.some(x => String(x.id) === String(id)),

    normalize: (str) => {
        if (!str) return "";
        return String(str).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    },

    levenshtein: (a, b) => {
        if(a.length === 0) return b.length; if(b.length === 0) return a.length;
        const matrix = [];
        for(let i=0; i<=b.length; i++) matrix[i] = [i];
        for(let j=0; j<=a.length; j++) matrix[0][j] = j;
        for(let i=1; i<=b.length; i++){
            for(let j=1; j<=a.length; j++){
                if(b.charAt(i-1) == a.charAt(j-1)) matrix[i][j] = matrix[i-1][j-1];
                else matrix[i][j] = Math.min(matrix[i-1][j-1] + 1, Math.min(matrix[i][j-1] + 1, matrix[i-1][j] + 1));
            }
        }
        return matrix[b.length][a.length];
    },

    confirm: (m,cb) => { $('u-title').innerText='Confirmation'; $('u-msg').innerText=m; $('u-input-group').classList.add('d-none'); const b=$('u-btn-confirm'), n=b.cloneNode(true); b.parentNode.replaceChild(n, b); n.innerText = "OK"; n.onclick=()=>{cb(); bootstrap.Modal.getInstance($('universalModal')).hide()}; new bootstrap.Modal($('universalModal')).show(); },
    prompt: (title, msg, cb) => { $('u-title').innerText = title; $('u-msg').innerText = msg; $('u-input-group').classList.remove('d-none'); const inp = $('u-input'); inp.value = ''; inp.type = 'text'; const b = $('u-btn-confirm'); const n = b.cloneNode(true); b.parentNode.replaceChild(n, b); n.innerText = "OK"; n.onclick = () => { if(!inp.value) return App.Utils.toast("Requis", "warning"); cb(inp.value); bootstrap.Modal.getInstance($('universalModal')).hide(); }; new bootstrap.Modal($('universalModal')).show(); },
    flyTo: (el, targetId) => { const btn=document.querySelector(targetId); if(!el||!btn)return; const f=el.cloneNode(), r=el.getBoundingClientRect(), t=btn.getBoundingClientRect(); f.className='flying-img'; Object.assign(f.style,{width:r.width+'px',height:r.height+'px',top:r.top+'px',left:r.left+'px'}); document.body.appendChild(f); setTimeout(()=>{ Object.assign(f.style,{top:t.top+'px',left:t.left+'px',width:'10px',height:'10px',opacity:0}); },50); setTimeout(()=>f.remove(),800); },
    showSkeletons: (cid,n=8) => { const r=$(cid); if(r) r.innerHTML=Array(n).fill('<div class="col-6 col-md-4 col-lg-3"><div class="product-card" style="height:250px;background:#f8f9fa;"></div></div>').join(''); },

    getStatus: (p) => {
        if(p.label === 'Sale') return { code: 'sale', label: 'PROMO', color: 'danger', icon: 'bi-tags-fill', buyable: true };
        if(p.label === 'Restock') return { code: 'restock', label: 'EN RÉAPPRO', color: 'warning', icon: 'bi-clock-history', buyable: false };
        if(p.stock <= 0) return { code: 'out', label: 'ÉPUISÉ', color: 'secondary', icon: 'bi-x-circle', buyable: false };
        return { code: 'available', label: '', color: 'success', icon: 'bi-check', buyable: true };
    }
  },

  Catalog: {
    searchTimer: null,
    init: () => {
      App.Utils.showSkeletons('product-grid-root');

      // Auto-hide dropdown on scroll
      window.addEventListener('scroll', () => { if(document.getElementById('search-suggestions')) App.Catalog.hideSuggestions(); });
      document.addEventListener('click', (e) => { if (!e.target.closest('.control-bar')) App.Catalog.hideSuggestions(); });

      const KEY = 'se_catalog_v6'; 
      const ld=localStorage.getItem(KEY); if(ld) { try{ App.Catalog.loadData(JSON.parse(ld)); } catch(e){} }
      fetch(API_URL+"?action=getCatalogJson").then(r=>r.json()).then(r=>{ 
          if(r.status==='success'&&r.data){ 
              try { localStorage.setItem(KEY,JSON.stringify(r.data)); } catch(e){}
              App.Catalog.loadData(r.data); 
          } 
      }).catch(e=>console.log("Offline"));
    },

    loadData: d => { 
        App.State.catalog = d;
        if(window.Fuse) {
            const options = { includeScore: true, keys: ['title.fr', 'title.en', 'category'], threshold: 0.4, ignoreLocation: true };
            App.State.fuse = new Fuse(d, options);
        }
        App.State.filtered = [...d]; 
        App.Catalog.render(true); 
        App.Home.render(); 
        App.Catalog.initScroll(); 

        // --- TRIGGER SYNC AFTER CATALOG LOAD ---
        if(App.State.user) App.API.fetchUserData(true);
    },

    hideSuggestions: () => { const b = document.getElementById('search-suggestions'); if(b) b.style.display = 'none'; document.getElementById('catalog-search-input').blur(); },
    clearSearch: () => { const inp = document.getElementById('catalog-search-input'); if(inp) { inp.value = ''; App.Catalog.handleSearch(inp); inp.focus(); } },

    handleSearch: (el) => {
        clearTimeout(App.Catalog.searchTimer);
        const val = el.value;
        const clearBtn = document.getElementById('search-clear-btn');
        if(clearBtn) clearBtn.style.display = val.length > 0 ? 'block' : 'none';

        App.Catalog.searchTimer = setTimeout(() => {
            const b=$('search-suggestions');
            if(val.length < 2){ b.innerHTML=''; b.style.display='none'; App.Catalog.search(val); return; }

            let hits = [];
            if(App.State.fuse) hits = App.State.fuse.search(val).slice(0,5).map(res => res.item);
            else hits = App.State.catalog.filter(p => App.Utils.normalize(App.Utils.text(p.title)).includes(App.Utils.normalize(val))).slice(0,5);

            b.innerHTML= hits.map(p=>`<div class="p-2 border-bottom bg-white small cursor-pointer" onclick="App.ProductPage.open('${p.id}'); App.Catalog.hideSuggestions();"><img src="${App.Utils.parseImg(p.image)}" class="suggestion-img" style="width:30px;height:30px;object-fit:contain;margin-right:10px;"><span>${App.Utils.text(p.title)}</span></div>`).join('');
            b.style.display = hits.length ? 'block' : 'none';
            App.Catalog.search(val);
        }, 300);
    },

    search: (q) => { 
        const stockMode = $('stock-filter-select').value; 
        let results = [];
        if(!q) results = [...App.State.catalog];
        else if (App.State.fuse) results = App.State.fuse.search(q).map(res => res.item);
        else { const term = App.Utils.normalize(q); results = App.State.catalog.filter(p => App.Utils.normalize(App.Utils.text(p.title)).includes(term)); }

        results = results.filter(p => {
            const status = App.Utils.getStatus(p);
            if (stockMode === 'in' && !status.buyable) return false;
            if (stockMode === 'out' && status.buyable) return false;
            return true;
        });

        App.State.filtered = results;
        App.Catalog.render(true); 
    },

    render: r => {
       const g=$('product-grid-root'); if(!g)return; if(r){ g.innerHTML=''; App.State.visibleCount=12; }
       const d=App.State.filtered.slice(0,App.State.visibleCount);
       if(!d.length){ g.innerHTML='<div class="text-center w-100 py-5 opacity-50">Aucun produit</div>'; return; }
       g.insertAdjacentHTML('beforeend', d.map(p=>App.Catalog.html(p)).join(''));
    },
    html: p => {
       const id=String(p.id).replace(/'/g,"\\'"), im=App.Utils.parseImg(p.image), fc=App.Utils.isFav(id)?'active':'', fi=App.Utils.isFav(id)?'bi-heart-fill':'bi-heart';
       const status = App.Utils.getStatus(p);
       return `<div class="col-6 col-md-4 col-lg-3"><div class="product-card ${!status.buyable ? 'opacity-75' : ''}" onclick="App.ProductPage.open('${id}')">${status.label ? `<span class="badge bg-${status.color} position-absolute top-0 start-0 m-2 shadow-sm" style="z-index:5; font-size:10px;">${status.label}</span>` : ''}<div class="card-actions"><div class="action-btn" onclick="event.stopPropagation();App.QuickView.open('${id}')"><i class="bi bi-eye"></i></div><div class="action-btn ${fc}" onclick="event.stopPropagation();App.Wishlist.toggle('${id}',this)"><i class="bi ${fi}"></i></div></div><div class="img-box"><img src="${im}" onerror="this.src='${IMG_FALLBACK}'" style="${!status.buyable ? 'filter:grayscale(100%);' : ''}"></div><div class="p-3"><div class="fw-bold small text-truncate">${App.Utils.text(p.title)}</div><div class="d-flex justify-content-between align-items-center mt-2"><span class="text-primary fw-bold">${App.Utils.fmt(p.price_MAD)}</span><button class="btn btn-sm btn-light rounded-circle border shadow-sm position-relative" style="z-index:2;" ${!status.buyable ? 'disabled' : ''} onclick="event.stopPropagation();App.Cart.add('${id}',this)"><i class="bi bi-plus-lg"></i></button></div></div></div></div>`;
    },
    renderNext: () => {
       if(App.State.visibleCount>=App.State.filtered.length) return;
       const n=App.State.filtered.slice(App.State.visibleCount, App.State.visibleCount+12);
       if(n.length){ App.State.visibleCount+=12; $('product-grid-root').insertAdjacentHTML('beforeend', n.map(p=>App.Catalog.html(p)).join('')); }
    },
    initScroll: () => { const s=$('scroll-sentinel'); if(s) new IntersectionObserver(e=>{if(e[0].isIntersecting)App.Catalog.renderNext()},{threshold:0.1}).observe(s); },
    cyclePriceSort: (btn) => { App.State.catalog.sort((a,b)=>parseFloat(a.price_MAD)-parseFloat(b.price_MAD)); App.Catalog.render(true); App.Utils.toast("Prix croissant"); const icon = btn.querySelector('i'); if(icon) icon.className = "bi bi-sort-numeric-down text-primary"; },
    openCategoryFilter: () => {
       const l=$('category-list-root'); if(!l)return;
       const cats=[...new Set(App.State.catalog.map(p=>p.category))].filter(Boolean).sort();
       l.innerHTML=cats.map(c=>`<button class="list-group-item list-group-item-action d-flex justify-content-between py-3" onclick="App.Catalog.selectCategory('${c}')"><span>${c}</span><span class="badge bg-light text-dark rounded-pill border">${App.State.catalog.filter(p=>p.category===c).length}</span></button>`).join('');
       if(document.activeElement) document.activeElement.blur(); new bootstrap.Modal($('categoryModal')).show();
    },
    selectCategory: c => { $('catalog-search-input').value = ""; App.State.filtered = (c==='all') ? [...App.State.catalog] : App.State.catalog.filter(p=>p.category===c); App.Catalog.render(true); const el=$('categoryModal'); if(el){ const m=bootstrap.Modal.getInstance(el); if(m) m.hide(); } App.Router.go('catalog'); }
  },

  Home: {
    render: () => {
       const r = $('recent-grid'); const c = $('cat-scroll-inner'); 
       if(!App.State.catalog || !App.State.catalog.length) return;
       const uCats = [...new Set(App.State.catalog.map(p => p.category))].filter(Boolean).sort();
       const im = { "E-liquids": "bi-droplet-fill", "Liquides": "bi-droplet-half", "Juice": "bi-bucket-fill", "Hardware": "bi-cpu-fill", "Mods": "bi-controller", "Box": "bi-hdd-fill", "Kits": "bi-box-seam-fill", "Puffs": "bi-cloud-fill", "Jetables": "bi-wind", "Disposable": "bi-cloud-haze2-fill", "Pods": "bi-capsule", "Cartridges": "bi-sd-card-fill", "Cartouches": "bi-sd-card", "Coils": "bi-lightning-fill", "Résistances": "bi-lightning-charge-fill", "Tanks": "bi-funnel-fill", "Atomiseurs": "bi-funnel", "Batteries": "bi-battery-charging", "Accus": "bi-battery-full", "Accessories": "bi-plug-fill", "Accessoires": "bi-tools", "DIY": "bi-eyedropper", "Cotton": "bi-flower1", "Chargers": "bi-lightning" };
       const generateCatHTML = () => uCats.map(x => { const icon = im[x] || 'bi-tag-fill'; return `<div class="cat-item" onclick="App.Catalog.selectCategory('${x.replace(/'/g, "\\'")}')"><div class="cat-icon shadow-sm"><i class="bi ${icon}"></i></div><div class="mt-2 fw-bold text-dark small text-truncate" style="max-width: 80px;">${x}</div></div>`; }).join('');
       c.innerHTML = generateCatHTML() + generateCatHTML();
       if(r) r.innerHTML = App.State.catalog.slice(0, 8).map(p => App.Catalog.html(p)).join('');
       App.Home.initAutoScroll();
    },
    initAutoScroll: () => {
        const container = document.querySelector('.cat-slider-container'); if (!container) return;
        setTimeout(() => {
            if (container.scrollWidth <= container.clientWidth) return;
            let scrollInterval; const scrollSpeed = 1; const tickRate = 20;
            const step = () => { if (container.scrollLeft >= (container.scrollWidth / 2)) { container.scrollLeft = container.scrollLeft - (container.scrollWidth / 2); } else { container.scrollLeft += scrollSpeed; } };
            const startScrolling = () => { if (scrollInterval) clearInterval(scrollInterval); scrollInterval = setInterval(step, tickRate); };
            const stopScrolling = () => { clearInterval(scrollInterval); };
            const resumeLater = () => { stopScrolling(); setTimeout(startScrolling, 3000); };
            container.addEventListener('mouseenter', stopScrolling); container.addEventListener('mouseleave', resumeLater); container.addEventListener('touchstart', stopScrolling); container.addEventListener('touchend', resumeLater); startScrolling();
        }, 100);
    }
  },

  Cart: {
    syncTimer: null,
    sync: () => {
        if(!App.State.user) return; clearTimeout(App.Cart.syncTimer);
        App.Cart.syncTimer = setTimeout(() => {
            const payload = { action: "syncUserData", type: "cart", authToken: App.State.user.authToken, items: JSON.stringify(App.State.cart.map(x=>({id:x.cartId, qty:x.qty}))), coupon: App.State.activeCode || "" };
            fetch(API_URL, {method:'POST', body:JSON.stringify(payload)});
        }, 2000);
    },
    // --- UPDATED ADD TO SUPPORT VARIANTS ---
    add: (id, btn, q = 1, variant = null) => { 
       if(btn) btn.blur(); 
       const p = App.State.catalog.find(x => String(x.id) === String(id)); if(!p) return;

       // Unique ID for Cart (ID + Variant)
       const cartId = variant ? `${id}-${variant}` : String(id);

       const ex = App.State.cart.find(c => c.cartId === cartId);
       if(ex) {
           ex.qty += q; 
       } else {
           App.State.cart.push({ 
               ...p, 
               cartId: cartId, // internal ID
               qty: q, 
               selectedVariant: variant,
               title: variant ? `${App.Utils.text(p.title)} (${variant})` : p.title
           });
       }

       if(btn) { const c = btn.closest('.product-card')||btn.closest('.modal-content'); if(c) App.Utils.flyTo(c.querySelector('img'), '.bi-bag-fill'); }
       App.Utils.toast(App.Utils.t('cart_updated') || "Ajouté"); 
       App.Cart.save(); App.Cart.render();
    },
    remove: id => { App.State.cart = App.State.cart.filter(x => String(x.cartId) !== String(id)); App.Cart.save(); App.Cart.render(); },
    togglePoints: c => { App.State.usePoints = c; App.Cart.render(); },
    applyCoupon: () => {
       const c = $('coupon-input').value.trim(); if(!c) return;
       const s = App.State.cart.reduce((a,b) => a + (parseFloat(b.price_MAD || 0) * b.qty), 0);
       fetch(API_URL, {method:'POST', body:JSON.stringify({action:"checkCoupon", code:c, total:s})}).then(r => r.json()).then(r => {
          if(r.status === 'success'){ App.State.discount = parseFloat(r.discount); App.State.activeCode = c; App.Utils.toast(`Code -${r.discount}%`); App.Cart.save(); App.Cart.render(); } 
          else { App.State.discount = 0; App.State.activeCode = null; App.Utils.toast(r.message || "Invalide", "danger"); App.Cart.render(); }
       });
    },
    save: () => { localStorage.setItem('se_cart', JSON.stringify(App.State.cart)); if(App.State.activeCode) localStorage.setItem('se_code', App.State.activeCode); App.Cart.sync(); },

    // --- UPDATED RENDER WITH SAVED ADDRESSES ---
    render: () => {
       const c = App.State.cart, l = $('cart-list'), b = $('nav-cart-count');
       if(b) { b.innerText = c.length; b.style.display = c.length ? 'flex' : 'none'; }

       if(!c.length) { 
           $('cart-empty-state').style.display = 'block'; 
           $('cart-summary-panel').style.display = 'none'; 
           l.innerHTML = ''; return; 
       }
       $('cart-empty-state').style.display = 'none'; 
       $('cart-summary-panel').style.display = 'block';

       l.innerHTML = c.map(i => `<div class="d-flex gap-3 mb-3 bg-white p-2 rounded shadow-sm align-items-center"><img src="${App.Utils.parseImg(i.image)}" width="50" height="50" class="rounded object-fit-contain"><div class="flex-grow-1 small"><div class="fw-bold text-truncate">${App.Utils.text(i.title)}</div><div>${i.qty} x ${App.Utils.fmt(i.price_MAD)}</div></div><button class="btn btn-sm text-danger" onclick="App.Cart.remove('${i.cartId}')"><i class="bi bi-trash"></i></button></div>`).join('');

       // Inject Saved Address Buttons if user logged in
       const addrSection = document.getElementById('saved-addr-buttons');
       if(!addrSection && App.State.user && App.State.addresses) {
            const addrs = App.State.addresses;
            const container = document.getElementById('chk-address');
            if(container) {
                const btns = document.createElement('div');
                btns.id = 'saved-addr-buttons';
                btns.className = 'd-flex gap-2 mb-2';
                let html = '';
                if(addrs.home) html += `<button class="btn btn-xs btn-outline-primary rounded-pill py-0" onclick="document.getElementById('chk-address').value = '${addrs.home.full || addrs.home.street}'"><i class="bi bi-house"></i> Domicile</button>`;
                if(addrs.office) html += `<button class="btn btn-xs btn-outline-dark rounded-pill py-0" onclick="document.getElementById('chk-address').value = '${addrs.office.full || addrs.office.street}'"><i class="bi bi-building"></i> Bureau</button>`;
                btns.innerHTML = html;
                if(html) container.parentNode.insertBefore(btns, container);
            }
       }

       App.Cart.calcTotals();
    },
    calcTotals: () => {
       const sub = App.State.cart.reduce((a,b) => a + (parseFloat(b.price_MAD || 0) * b.qty), 0);
       const couponPct = App.State.discount || 0; const couponAmt = (sub * couponPct) / 100; 
       const uPoints = App.State.userPoints || 0; const tempTotal = Math.max(0, sub - couponAmt);
       const lSec = $('loyalty-section'); if(lSec) lSec.style.display = (uPoints > 0) ? 'flex' : 'none';
       const ptsAmt = (App.State.usePoints && uPoints > 0) ? Math.min(tempTotal, uPoints) : 0;
       const minShip = App.State.config?.shipping_min || 100; const shipCost = (sub >= minShip) ? 0 : (App.State.config?.shipping_cost || 20);
       const finalTotal = Math.max(0, tempTotal - ptsAmt + shipCost);
       $('summary-subtotal').innerText = App.Utils.fmt(sub);
       const rc = $('row-discount-coupon'); if(rc) { rc.style.display = (couponAmt > 0) ? 'flex' : 'none'; $('val-discount-coupon').innerText = '-' + App.Utils.fmt(couponAmt); }
       const rp = $('row-discount-points'); if(rp) { rp.style.display = (ptsAmt > 0) ? 'flex' : 'none'; $('val-discount-points').innerText = '-' + App.Utils.fmt(ptsAmt); }
       $('cart-total').innerText = App.Utils.fmt(finalTotal);
       // Progress Bar Logic
       const bar = document.getElementById('free-shipping-bar');
       if(bar) {
           const pct = Math.min(100, (sub / minShip) * 100);
           bar.style.width = pct + "%";
           document.getElementById('free-shipping-text').innerText = pct >= 100 ? "Livraison Gratuite !" : `Plus que ${minShip - sub} DH pour livraison gratuite`;
       }
    },
    checkout: () => {
       const n = $('chk-name').value, p = $('chk-phone').value, a = $('chk-address').value;
       if(!n || !p || !a) return App.Utils.toast("Remplissez l'adresse");
       const btn = $('btn-checkout'); if(btn){ btn.disabled = true; btn.innerText = "Envoi..."; btn.blur(); }
       const sub = App.State.cart.reduce((a,b) => a + (parseFloat(b.price_MAD) * b.qty), 0);
       const finalTotal = parseFloat($('cart-total').innerText.replace(' DH','')); 
       let msg = `*NOUVELLE COMMANDE* 🛒\n👤 ${n}\n📞 ${p}\n📍 ${a}\n\n`;
       App.State.cart.forEach(i => msg += `▫️ ${i.qty}x ${App.Utils.text(i.title)}\n`);
       if(App.State.activeCode) msg += `\n🎟 Code: ${App.State.activeCode} (-${App.State.discount}%)`;
       msg += `\n💰 TOTAL: ${App.Utils.fmt(finalTotal)}`;
       fetch(API_URL, {method:'POST', body:JSON.stringify({action: "placeOrder", data: { name: n, phone: p, address: a, total: finalTotal, cart: JSON.stringify(App.State.cart.map(x => ({id:x.id, title:App.Utils.text(x.title), qty:x.qty}))), pointsUsed: (App.State.usePoints && App.State.user)?Math.min(sub, App.State.userPoints):0, coupon: App.State.activeCode || "", authToken: App.State.user?.authToken || "Guest"}})}).then(r => r.json()).then(r => {
          if(btn) { btn.disabled = false; btn.innerText = "COMMANDER"; }
          if(r.status === 'success') {
             App.State.lastOrder = { id: r.orderId, msg: msg };
             if($('display-order-id')) $('display-order-id').innerText = "#" + r.orderId;
             App.State.cart = []; App.State.discount = 0; App.State.activeCode = null; App.Cart.save(); App.Cart.render();
             App.Router.go('thanks'); if(window.confetti) confetti();
          } else App.Utils.toast("Erreur: " + r.message, "danger");
       });
    },
    sendToWhatsApp: () => {
        if(!App.State.lastOrder) return;
        const num = App.State.config?.whatsapp || "212661552233"; 
        window.open(`https://wa.me/${num}?text=${encodeURIComponent(App.State.lastOrder.msg)}`, '_blank');
    }
  },

  Admin: {
     login: () => {
        const inp=$('u-input'); $('u-title').innerText = 'Admin'; $('u-msg').innerText = 'PIN:'; $('u-input-group').classList.remove('d-none'); inp.value=''; inp.type='password';
        const m=new bootstrap.Modal($('universalModal')); const b=$('u-btn-confirm'); const n=b.cloneNode(true); b.parentNode.replaceChild(n,b); n.innerText = "OK"; n.disabled = false;
        n.onclick=()=>{
            const c=inp.value; if(!c) return; n.innerText="..."; n.disabled=true;
            fetch(`${API_URL}?action=getAdminDashboard&pw=${c}`).then(r=>r.json()).then(r=>{
                n.innerText="OK"; n.disabled=false;
                if(r.status==='success'){ App.State.adminPw=c; App.State.tempOrders=r.orders; m.hide(); App.Router.go('admin'); App.Admin.renderOrders(r.orders); }
                else{ App.Utils.toast("Incorrect", "danger"); inp.value=""; }
            }).catch(e => { n.innerText="OK"; n.disabled=false; App.Utils.toast("Erreur", "danger"); });
        }; m.show();
     },
     fetchOrders: () => { if(!App.State.adminPw) return App.Admin.login(); fetch(`${API_URL}?action=getAdminDashboard&pw=${App.State.adminPw}`).then(r=>r.json()).then(r=>{ if(r.status==='success') { App.State.tempOrders=r.orders; App.Admin.renderOrders(r.orders); } }); },
     renderOrders: (orders) => { 
        const bg = s => ({'Pending':'warning','Shipped':'info','Delivered':'success','Cancelled':'danger', 'Confirmed':'primary'}[s] || 'secondary');
        $('admin-orders-list').innerHTML = orders.map(o => `
            <div class="card p-3 mb-2 border-0 shadow-sm">
                <div class="d-flex justify-content-between align-items-center mb-2"><strong>#${o.id}</strong>
                <select class="form-select form-select-sm w-auto py-0 px-2 text-${bg(o.status)} fw-bold border-${bg(o.status)}" onchange="App.Admin.setStatus('${o.id}',this.value)" style="height:25px;font-size:0.8rem;">
                    <option value="Pending" ${o.status=='Pending'?'selected':''}>En Attente</option>
                    <option value="Confirmed" ${o.status=='Confirmed'?'selected':''}>Confirmé</option>
                    <option value="Shipped" ${o.status=='Shipped'?'selected':''}>Expédié</option>
                    <option value="Delivered" ${o.status=='Delivered'?'selected':''}>Livré</option>
                    <option value="Cancelled" ${o.status=='Cancelled'?'selected':''}>Annulé</option>
                </select></div>
                <div class="d-flex justify-content-between small text-muted"><span>${o.name}</span><span class="fw-bold text-dark">${App.Utils.fmt(o.total)}</span></div>
                <div class="text-end mt-2"><button class="btn btn-sm btn-light rounded-circle border" onclick="App.Profile.showOrderDetail('${o.id}')"><i class="bi bi-eye-fill text-primary"></i></button><a href="tel:${o.phone}" class="btn btn-sm btn-light rounded-circle border"><i class="bi bi-telephone-fill text-success"></i></a><a href="https://wa.me/${String(o.phone).replace(/\D/g,'')}" target="_blank" class="btn btn-sm btn-light rounded-circle border"><i class="bi bi-whatsapp text-success"></i></a></div>
            </div>`).join('');
     },
     setStatus: (oid, s) => {
         const ord = App.State.tempOrders.find(x=>String(x.id)===String(oid)); if(ord) { ord.status = s; App.Admin.renderOrders(App.State.tempOrders); }
         fetch(API_URL,{method:'POST',body:JSON.stringify({action:"updateOrderStatus",password:App.State.adminPw,data:{orderId:oid,status:s}})}).then(r=>r.json()).then(r=>{ if(r.status==='success') App.Utils.toast("Statut mis à jour"); });
     },
     fetchReviews: () => {
        $('admin-reviews-list').innerHTML = '<div class="text-center py-4"><div class="spinner-border text-primary"></div></div>';
        fetch(`${API_URL}?action=getAdminReviews&pw=${App.State.adminPw}`).then(r=>r.json()).then(r=>{ if(r.status === 'success') App.Admin.renderReviews(r.reviews); });
     },
     renderReviews: (list) => {
        if(!list.length) return $('admin-reviews-list').innerHTML = '<div class="text-center text-muted py-5">Aucun avis.</div>';
        $('admin-reviews-list').innerHTML = list.map(r => `
            <div class="card p-3 mb-2 border-0 shadow-sm">
                <div class="d-flex justify-content-between mb-1"><span class="fw-bold text-dark small">${r.product}</span><span class="badge ${r.status==='Active'?'bg-success':'bg-warning text-dark'}">${r.status}</span></div>
                <div class="small text-warning mb-1">${"★".repeat(r.rating)} <span class="text-muted">par ${r.user}</span></div>
                <div class="bg-light p-2 rounded small mb-2 fst-italic text-muted">"${r.comment}"</div>
                <div class="d-flex gap-2 justify-content-end">${r.status !== 'Active' ? `<button class="btn btn-sm btn-success rounded-pill px-3 fw-bold" onclick="App.Admin.setRevStatus('${r.id}','Active', this)">Approuver</button>` : ''}<button class="btn btn-sm btn-outline-danger rounded-pill px-3" onclick="App.Admin.setRevStatus('${r.id}','Rejected', this)">Rejeter</button></div>
            </div>`).join('');
     },
     setRevStatus: (id, status, btn) => {
        btn.innerText = "..."; btn.disabled = true;
        fetch(API_URL,{method:'POST',body:JSON.stringify({action:"updateReviewStatus",password:App.State.adminPw,data:{reviewId:id, status:status}})}).then(r=>r.json()).then(r=>{ if(r.status==='success') { App.Utils.toast("Avis mis à jour"); App.Admin.fetchReviews(); } else { btn.disabled=false; App.Utils.toast("Erreur","danger"); } });
     },
     setView: v => { 
         if(v === 'repair') { if(confirm("Repair DB Headers?")) fetch(`${API_URL}?action=repairDatabase&pw=${App.State.adminPw}`).then(()=>App.Utils.toast("OK")); return; }
         const bo=$('adm-btn-ord'), bc=$('adm-btn-cat'), br=$('adm-btn-rev');
         if(bo && bc && br) { const active = 'btn btn-sm btn-dark rounded-pill px-3'; const inactive = 'btn btn-sm btn-outline-secondary border-0 rounded-pill px-3'; bo.className = v==='orders' ? active : inactive; bc.className = v==='catalog' ? active : inactive; br.className = v==='reviews' ? active : inactive; }
         if($('admin-orders-view')) $('admin-orders-view').style.display=v=='orders'?'block':'none'; 
         if($('admin-catalog-panel')) $('admin-catalog-panel').style.display=v=='catalog'?'block':'none'; 
         if($('admin-reviews-view')) $('admin-reviews-view').style.display=v=='reviews'?'block':'none';
         if(v=='orders') App.Admin.fetchOrders(); if(v=='catalog') App.Admin.renderCatalog(); if(v=='reviews') App.Admin.fetchReviews();
     },
     renderCatalog: () => { 
         const q = $('admin-catalog-search').value.toLowerCase();
         const items = App.State.catalog.filter(p => App.Utils.text(p.title).toLowerCase().includes(q)).slice(0, 50);
         $('admin-catalog-items').innerHTML=items.map(p=>`
            <div class="d-flex align-items-center justify-content-between p-2 border-bottom bg-white">
                <div class="d-flex align-items-center gap-3" style="width: 55%;"><img src="${App.Utils.parseImg(p.image)}" style="width:40px; height:40px; object-fit:contain; border-radius:6px; border:1px solid #eee;"><div style="line-height:1.2;"><div class="small fw-bold text-truncate">${App.Utils.text(p.title)}</div><div class="x-small text-muted">${p.category}</div></div></div>
                <div class="d-flex align-items-center gap-2"><button class="btn btn-sm btn-light border py-0 px-2 small fw-bold" onclick="App.Admin.editPrice('${p.id}')">${p.price_MAD}</button>
                <select class="form-select form-select-sm" style="width: 100px; font-size:10px;" onchange="App.Admin.updateStatus('${p.id}', this.value)"><option value="available" ${p.stock > 0 && !p.label ? 'selected' : ''}>Dispo</option><option value="out" ${p.stock <= 0 && !p.label ? 'selected' : ''}>Épuisé</option><option value="sale" ${p.label === 'Sale' ? 'selected' : ''}>Promo</option><option value="restock" ${p.label === 'Restock' ? 'selected' : ''}>Réappro</option></select>
                </div>
            </div>`).join(''); 
     },
     updateStatus: (id, status) => {
         fetch(API_URL, {method: 'POST', body: JSON.stringify({ action: "updateProductStatus", password: App.State.adminPw, data: { productId: id, status: status } })})
         .then(r => r.json()).then(res => { if(res.status === "success") { App.Utils.toast("Statut mis à jour ✅"); const item = App.State.catalog.find(p => p.id === id); if(item) { if(status === 'available') { item.stock = 100; item.label = ""; } if(status === 'out') { item.stock = 0; item.label = ""; } if(status === 'sale') { item.stock = 100; item.label = "Sale"; } if(status === 'restock') { item.stock = 0; item.label = "Restock"; } } App.Admin.renderCatalog(); } else { App.Utils.toast("Erreur", "danger"); } });
     },
     editPrice: id => { App.Utils.prompt("Prix", "Nouveau prix:", (p) => { if(p) { fetch(API_URL,{method:'POST',body:JSON.stringify({action:"updatePrice",password:App.State.adminPw,data:{productId:id,price:p}})}).then(()=>{ App.Utils.toast("Succès"); App.State.catalog.find(x=>x.id==id).price_MAD=p; App.Admin.renderCatalog(); }); } }); }
  },



  CPanel: {
    data: {},

    // Login with Root PIN
    login: () => {
        App.Utils.prompt("SuperAdmin", "Root PIN:", (pw) => {
            // Save to rootPw, NOT adminPw
            App.State.rootPw = pw;
            App.CPanel.init();
        });
    },

    // Initialize with rootPw
    init: () => {
        const pw = App.State.rootPw;
        if(!pw) return App.CPanel.login();

        App.Utils.toast("Loading...");

        fetch(`${API_URL}?action=getCPanelData&pw=${pw}`).then(r=>r.json()).then(res => {
            if(res.status === 'success') {
                App.CPanel.data = res;
                App.Router.go('cpanel');
                App.CPanel.render();
            } else {
                App.Utils.toast("Accès Refusé 🛑", "danger");
            }
        });
    },

    render: () => {
        const d = App.CPanel.data;
        if(!d || !d.stats) return; // Safety check

        // 1. Stats
        $('stat-products').innerText = d.stats.products;
        $('stat-orders').innerText = d.stats.orders;
        $('stat-reviews').innerText = d.stats.reviews;

        // 2. Config
        const cfg = d.config || {};
        if($('mod-maintenance')) $('mod-maintenance').checked = (cfg['maintenance'] === "TRUE");
        if($('mod-reviews')) $('mod-reviews').checked = (cfg['Module_Reviews'] === "TRUE");
        if($('mod-shipping-bar')) $('mod-shipping-bar').checked = (cfg['show_shipping_bar'] !== "FALSE");

        $('set-whatsapp').value = cfg['whatsapp_number'] || '';
        $('set-ship-min').value = cfg['shipping_min'] || '';
        $('set-ship-cost').value = cfg['shipping_cost'] || '';

        $('set-ban-title').value = cfg['banner_title'] || '';
        $('set-ban-desc').value = cfg['banner_desc'] || '';
        $('set-ban-btn').value = cfg['banner_btn'] || '';

        // 3. Users
        App.CPanel.renderUsers(d.users);
    },

    renderUsers: (users) => {
        if(!users) return;
        $('cp-user-list').innerHTML = users.map(u => `
            <tr>
                <td><div class="fw-bold">${u.name}</div><div class="x-small text-muted">${u.phone}</div></td>
                <td><span class="badge ${u.role==='admin'?'bg-danger':'bg-secondary'}">${u.role}</span></td>
                <td>${u.points} pts</td>
                <td>
                    ${u.role !== 'admin' ? 
                    `<button class="btn btn-sm btn-outline-danger" onclick="App.CPanel.setUserRole('${u.id}', 'banned')">Ban</button>
                     <button class="btn btn-sm btn-outline-success" onclick="App.CPanel.setUserRole('${u.id}', 'admin')">Promote</button>` 
                    : '<span class="text-muted small">SuperUser</span>'}
                </td>
            </tr>
        `).join('');
    },

    filterUsers: (q) => {
        if(!App.CPanel.data.users) return;
        const term = q.toLowerCase();
        const filtered = App.CPanel.data.users.filter(u => u.name.toLowerCase().includes(term) || String(u.phone).includes(term));
        App.CPanel.renderUsers(filtered);
    },

    tab: (id) => {
        document.querySelectorAll('.cpanel-tab').forEach(el => el.style.display = 'none');
        document.getElementById(`cp-tab-${id}`).style.display = 'block';
        document.getElementById('cpanel-page-title').innerText = id.charAt(0).toUpperCase() + id.slice(1);
    },

    saveConfig: (isSettings = false) => {
        const updates = {};
        if (isSettings) {
            updates['whatsapp_number'] = $('set-whatsapp').value;
            updates['shipping_min'] = $('set-ship-min').value;
            updates['shipping_cost'] = $('set-ship-cost').value;
            updates['banner_title'] = $('set-ban-title').value;
            updates['banner_desc'] = $('set-ban-desc').value;
            updates['banner_btn'] = $('set-ban-btn').value;
        } else {
            updates['maintenance'] = $('mod-maintenance').checked ? "TRUE" : "FALSE";
            updates['Module_Reviews'] = $('mod-reviews').checked ? "TRUE" : "FALSE";
            updates['show_shipping_bar'] = $('mod-shipping-bar').checked ? "TRUE" : "FALSE";
        }

        App.Utils.toast("Saving...");
        fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify({
                action: 'saveSystemConfig',
                password: App.State.rootPw, // Use Root PIN
                data: { updates: updates }
            })
        }).then(r=>r.json()).then(res => {
            if(res.status === 'success') App.Utils.toast("Saved Successfully ✅");
            else App.Utils.toast("Error Saving", "danger");
        });
    },

    setUserRole: (uid, role) => {
        if(!confirm(`Change role to ${role}?`)) return;
        fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify({
                action: 'updateUserRole',
                password: App.State.rootPw, // Use Root PIN
                data: { userId: uid, role: role }
            })
        }).then(r=>r.json()).then(res => {
            if(res.status === 'success') {
                App.Utils.toast("Updated");
                const u = App.CPanel.data.users.find(x => x.id === uid);
                if(u) u.role = role;
                App.CPanel.renderUsers(App.CPanel.data.users);
            }
        });
    }
  },


  QuickView: {
      open: id => {
          const p = App.State.catalog.find(x => String(x.id) === String(id)); if (!p) return;
          const im = App.Utils.parseImg(p.image), fc = App.Utils.isFav(id) ? 'active' : '', fi = App.Utils.isFav(id) ? 'bi-heart-fill' : 'bi-heart';
          $('qv-body').innerHTML = `
              <div class="parallax-wrapper">
                  <div class="sticky-img-header"><button class="action-btn ${fc} position-absolute top-0 start-0 m-3 z-3" onclick="App.Wishlist.toggle('${p.id}',this)"><i class="bi ${fi}"></i></button><img src="${im}"></div>
                  <div class="sliding-glass-sheet text-center">
                      <div class="bg-secondary opacity-25 rounded-pill mx-auto mb-3" style="width: 40px; height: 5px;"></div><div class="badge bg-primary bg-opacity-10 text-primary border-0 mb-2">${p.category}</div><h3 class="fw-bold text-dark mb-1">${App.Utils.text(p.title)}</h3><div class="text-primary fs-2 fw-bold mb-3">${App.Utils.fmt(p.price_MAD)}</div><hr class="opacity-10 mx-auto w-50 my-4"/><div class="text-secondary small mx-auto" style="line-height:1.7;">${p.desc ? App.Utils.text(p.desc) : 'Aucune description disponible.'}</div>
                  </div>
                  <div class="sticky-action-bar"><div class="qty-pill"><button class="qty-btn" onclick="App.QuickView.upd(-1)">-</button><span class="fw-bold fs-5" id="qv-qty">1</span><button class="qty-btn" onclick="App.QuickView.upd(1)">+</button></div><button class="btn btn-primary rounded-pill flex-grow-1 h-100 fw-bold shadow-sm" onclick="App.QuickView.add('${p.id}')">AJOUTER</button></div>
              </div>`;
          App.State.qvQty = 1; new bootstrap.Modal($('qvModal')).show();
      },
      upd: d => { App.State.qvQty = Math.max(1, App.State.qvQty + d); const e=$('qv-qty'); if(e)e.innerText=App.State.qvQty; },
      add: id => { App.Cart.add(id, null, App.State.qvQty); bootstrap.Modal.getInstance($('qvModal')).hide(); }
  },

  ProductPage: {
    selectedVariant: null, // NEW: Track selected variant
    open: id => {
      const p = App.State.catalog.find(x => String(x.id) === String(id)); if (!p) return;
      App.ProductPage.selectedVariant = null; // Reset selection
      const variants = p.variant_name ? p.variant_name.split(',').filter(v=>v) : [];

      const variantHtml = variants.length > 0 ? `
         <div class="mb-4">
             <label class="x-small fw-bold text-muted text-uppercase mb-2">Options :</label>
             <div class="d-flex flex-wrap gap-2" id="pd-variant-container">
                 ${variants.map(v => `<button class="btn btn-sm btn-outline-secondary rounded-pill px-3 py-1" onclick="App.ProductPage.selectVariant(this, '${v.trim()}')">${v.trim()}</button>`).join('')}
             </div>
         </div>` : '';

      $('pd-content-root').innerHTML = `<div class="parallax-wrapper" style="height: 85vh;"><div class="sticky-img-header" style="height:40vh;"><img src="${App.Utils.parseImg(p.image)}" style="max-height: 300px;"></div><div class="sliding-glass-sheet text-center" style="min-height: 80vh;"><div class="bg-secondary opacity-25 rounded-pill mx-auto mb-4" style="width:40px; height:5px;"></div><h1 class="fw-bold text-dark display-6 mb-2">${App.Utils.text(p.title)}</h1><div class="text-primary fs-1 fw-bold mb-3">${App.Utils.fmt(p.price_MAD)}</div><p class="text-muted text-uppercase fw-bold small tracking-wide">${p.category}</p>

      ${variantHtml}

      <div class="text-secondary mx-auto mt-4 px-2" style="max-width: 600px; line-height: 1.8; font-size: 1rem; padding-bottom: 20px;">${p.desc ? App.Utils.text(p.desc) : 'Pas de description.'}</div><div id="reviews-container" class="mt-5 text-start px-3"><h6>Avis Clients</h6><div id="reviews-list" class="small text-muted">Chargement...</div><button class="btn btn-sm btn-outline-primary rounded-pill mt-3" onclick="App.Reviews.openAdd('${p.id}')">+ Laisser un avis</button></div><div style="height:120px;"></div></div><div class="sticky-action-bar"><div class="qty-pill"><button class="qty-btn" onclick="App.ProductPage.upd(-1)">-</button><span class="fw-bold fs-5" id="pd-qty">1</span><button class="qty-btn" onclick="App.ProductPage.upd(1)">+</button></div><button class="btn btn-primary rounded-pill flex-grow-1 h-100 fw-bold shadow-sm" onclick="App.ProductPage.add('${p.id}')">AJOUTER</button></div></div>`;
      App.State.pdQty = 1; App.Router.go('product-detail'); App.Reviews.fetch(id);
    },
    selectVariant: (btn, name) => {
        document.querySelectorAll('#pd-variant-container button').forEach(b => { b.classList.remove('btn-dark','text-white'); b.classList.add('btn-outline-secondary'); });
        btn.classList.remove('btn-outline-secondary'); btn.classList.add('btn-dark','text-white');
        App.ProductPage.selectedVariant = name;
    },
    upd: d => { App.State.pdQty = Math.max(1, (App.State.pdQty||1) + d); const e=$('pd-qty'); if(e)e.innerText=App.State.pdQty; },
    add: id => { 
        const p = App.State.catalog.find(x => String(x.id) === String(id));
        if(p && p.variant_name && !App.ProductPage.selectedVariant) return App.Utils.toast("Veuillez choisir une option", "warning");
        App.Cart.add(id, null, App.State.pdQty, App.ProductPage.selectedVariant); 
        App.Router.go('cart'); 
    }
  },

  Reviews: {
    fetch: id => {
      fetch(`${API_URL}?action=getReviews&productId=${id}&t=${Date.now()}`).then(r=>r.json()).then(r=>{
        const l=$('reviews-list'); if(!l)return;
        l.innerHTML = r.reviews.length ? r.reviews.map(v=>`<div class="mb-3 border-bottom pb-2"><strong>${v.name}</strong> <span class="text-warning">${"★".repeat(v.rating)}</span><br>${v.comment}</div>`).join('') : "Aucun avis pour le moment.";
      });
    },
    openAdd: id => {
      if(!App.State.user) return App.Utils.toast("Connectez-vous pour noter",'danger');
      $('u-title').innerText = App.Utils.t('btn_write_review') || 'Noter le produit';
      $('u-msg').innerHTML = `<div class="mb-3"><label class="form-label small fw-bold">Note</label><select id="rev-rating" class="form-select rounded-pill"><option value="5">★★★★★ (5)</option><option value="4">★★★★ (4)</option><option value="3">★★★ (3)</option></select></div><div class="mb-3"><textarea id="rev-comment" class="form-control rounded-4" rows="3" placeholder="Votre avis..."></textarea></div>`;
      $('u-input-group').classList.add('d-none');
      const b=$('u-btn-confirm'); const n=b.cloneNode(true); b.parentNode.replaceChild(n,b);
      n.innerText = "Publier"; n.disabled = false;
      n.onclick=()=>{
        const rating = document.getElementById('rev-rating').value, comm = document.getElementById('rev-comment').value;
        if(!comm) return App.Utils.toast("Commentaire requis", "warning");
        n.innerText = "..."; n.disabled = true;
        fetch(API_URL,{method:'POST',body:JSON.stringify({action:"addReview",token:App.State.user.authToken,data:{productId:id,rating:rating,comment:comm}})}).then(()=>{ App.Utils.toast("Avis publié !"); bootstrap.Modal.getInstance($('universalModal')).hide(); setTimeout(() => { App.Reviews.fetch(id); }, 2500); }).catch(() => { n.innerText = "Publier"; n.disabled = false; App.Utils.toast("Erreur", "danger"); });
      };
      new bootstrap.Modal($('universalModal')).show();
    }
  },
  Wishlist: {
    toggle: (id, btn) => {
       const idx=App.State.wishlist.findIndex(x=>String(x.id)===String(id));
       if(idx>-1){ App.State.wishlist.splice(idx,1); if(btn&&btn.classList){btn.classList.remove('active'); const i=btn.querySelector('i'); if(i){i.className="bi bi-heart";}} App.Utils.toast("Retiré"); } 
       else{ const p=App.State.catalog.find(x=>String(x.id)===String(id)); if(p){ App.State.wishlist.push(p); if(btn&&btn.classList){btn.classList.add('active'); const i=btn.querySelector('i'); if(i){i.className="bi bi-heart-fill";}} if(btn) App.Utils.flyTo(btn, '.bi-heart-fill'); App.Utils.toast("Ajouté"); } }
       localStorage.setItem('se_wishlist',JSON.stringify(App.State.wishlist)); App.Wishlist.render();
    },
    clear: () => { App.Utils.confirm(App.Utils.t('wish_clear_msg') || "Vider la liste ?", () => { App.State.wishlist=[]; App.Wishlist.render(); localStorage.removeItem('se_wishlist'); App.Utils.toast("Liste vidée"); }); },
    render: () => {
       const r=$('wishlist-grid'), b=$('nav-wish-count'); if(!r)return;
       r.innerHTML=App.State.wishlist.length ? App.State.wishlist.map(p=>App.Catalog.html(p)).join('') : "";
       $('wishlist-empty').style.display=App.State.wishlist.length?'none':'block';
       if(b) { b.innerText=App.State.wishlist.length; b.style.display=App.State.wishlist.length?'flex':'none'; }
    }
  },

  Auth: {
    login: () => {
       const p=$('login-phone').value, pw=$('login-pass').value; if(!p||!pw)return App.Utils.toast("Remplir tout");
       fetch(API_URL,{method:'POST',body:JSON.stringify({action:"login",data:{phone:p,password:pw}})}).then(r=>r.json()).then(r=>{
         if(r.status==='success'){ localStorage.setItem('se_user',JSON.stringify(r.user)); App.Auth.restoreSession(r.user); App.Utils.toast("Connecté"); }
         else App.Utils.toast(r.message,'danger');
       });
    },
    logout: () => { localStorage.removeItem('se_user'); location.reload(); },
    restoreSession: u => {
       if(!u)return; App.State.user=u; $('auth-forms-container').style.display='none'; $('user-dashboard').style.display='block';
       $('dash-name-display').innerText=u.name; $('dash-phone-display').innerText=u.phone;
       if(['admin','merchant'].includes(u.role)) $('btn-admin-trigger').style.display='block';
       App.API.fetchUserData(); // TRIGGER CLOUD SYNC
       App.Profile.fetchOrders();
    }
  },

  Profile: {
    fetchOrders: () => {
       if(!App.State.user) return;
       fetch(`${API_URL}?action=getUserOrders&token=${App.State.user.authToken}`).then(r=>r.json()).then(r=>{
         if(r.status==='success'){
            const pts = document.getElementById('user-points-display');
            if(pts) pts.innerText = App.State.user.points || 0; 
            const cnt = document.getElementById('user-orders-count');
            if(cnt) cnt.innerText = r.orders.length;

            const historyList = document.getElementById('user-order-history');
            if(historyList) {
                historyList.innerHTML = r.orders.map(o => `
                <div class="card border-0 shadow-sm p-3 mb-2 rounded-4" style="background:#fff;">
                    <div class="d-flex justify-content-between mb-2"><strong>#${o.id}</strong><span class="badge bg-light text-dark border">${o.status}</span></div>
                    <div class="small text-muted mb-3">${App.Utils.fmt(o.total)} • ${o.date.split('T')[0]}</div>
                    <button class="btn btn-sm btn-outline-dark w-100 rounded-pill fw-bold" onclick="App.Profile.showOrderDetail('${o.id}')">Voir Détails</button>
                </div>`).join('');
            }
            App.State.tempOrders = r.orders;
         }
       });
    },

    // --- NEW: RENDER ADDRESSES ---
    renderAddresses: () => {
        const grid = document.getElementById('address-list-grid');
        if(!grid) return;

        const list = App.State.addresses || [];
        if(list.length === 0) {
            grid.innerHTML = '<div class="text-center text-muted py-4 small">Aucune adresse enregistrée.</div>';
            return;
        }

        // Handle both Array (Backend) and Object (Local legacy) formats
        const addrArray = Array.isArray(list) ? list : Object.values(list);

        grid.innerHTML = addrArray.map(a => {
            // Safety check for data fields
            const type = a.type || "Adresse";
            const val = a.val || a.street || "Position GPS";
            const icon = type === 'Home' ? 'bi-house' : 'bi-building';

            return `
            <div class="col-12">
                <div class="card border-0 shadow-sm p-3 rounded-4 mb-2">
                    <div class="d-flex align-items-center gap-3">
                        <div class="bg-light rounded-circle d-flex align-items-center justify-content-center" style="width:40px; height:40px;">
                            <i class="bi ${icon} text-primary"></i>
                        </div>
                        <div class="flex-grow-1">
                            <div class="fw-bold small">${type}</div>
                            <div class="text-muted x-small text-truncate" style="max-width: 200px;">${val}</div>
                        </div>
                        <button class="btn btn-sm text-secondary" onclick="App.Profile.openAddressModal()"><i class="bi bi-pencil"></i></button>
                    </div>
                </div>
            </div>`;
        }).join('');
    },

    showOrderDetail: oid => {
       const o = App.State.tempOrders.find(x => String(x.id) === String(oid)); if (!o) return;
       let items = []; try { items = JSON.parse(o.items); } catch(e) { items = []; }
       const itemsHtml = items.map(x => {
           const p = App.State.catalog.find(c => String(c.id) === String(x.id));
           const title = p ? App.Utils.text(p.title) : (x.title || 'Produit Inconnu');
           const img = p ? App.Utils.parseImg(p.image) : IMG_FALLBACK;
           return `<div class="d-flex align-items-center gap-3 mb-2 border-bottom pb-2"><div class="rounded border d-flex align-items-center justify-content-center flex-shrink-0" style="width:50px; height:50px; background:#fff;"><img src="${img}" style="max-width:100%; max-height:100%; object-fit:contain; mix-blend-mode:multiply;"></div><div class="flex-grow-1" style="min-width:0;"> <div class="d-flex align-items-baseline"><span class="fw-bold text-primary me-2 text-nowrap">${x.qty}x</span> <span class="text-dark small fw-bold text-truncate d-block">${title}</span></div></div></div>`;
       }).join('');

       let btnHtml = App.State.adminPw ? 
           `<button class="btn btn-danger w-100 rounded-pill mt-3 fw-bold" onclick="App.Admin.setStatus('${o.id}', 'Cancelled'); bootstrap.Modal.getInstance($('orderDetailModal')).hide();">ANNULER (ADMIN)</button>` : 
           `<button class="btn btn-danger w-100 rounded-pill mt-3 fw-bold" onclick="App.Profile.cancelOrder('${o.id}')">ANNULER LA COMMANDE</button>`;

       $('order-detail-body').innerHTML = `<div class="d-flex justify-content-between align-items-center mb-4"><h5 class="fw-bold m-0">Commande #${o.id}</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="mb-4 small text-muted"><div>Date: ${o.date.split('T')[0]}</div><div>Statut: <span class="badge bg-secondary">${o.status}</span></div></div><div class="bg-light p-3 rounded-4 mb-3 border" style="max-height:300px; overflow-y:auto;">${itemsHtml || '<div class="text-center small text-muted">Détails non disponibles</div>'}</div><div class="d-flex justify-content-between fw-bold fs-5 px-2"><span>Total</span><span class="text-primary">${App.Utils.fmt(o.total)}</span></div>${btnHtml}`;
       new bootstrap.Modal($('orderDetailModal')).show();
    },
    openAddressModal: () => new bootstrap.Modal($('addressModal')).show(),
    getLocation: (btn) => {
        if(!navigator.geolocation) return App.Utils.toast("Non supporté");
        const oldText = btn.innerText; btn.disabled = true; btn.innerText = "...";
        navigator.geolocation.getCurrentPosition((pos) => { $('addr-gps').value = `https://www.google.com/maps?q=${pos.coords.latitude},${pos.coords.longitude}`; btn.innerText = oldText; btn.disabled = false; App.Utils.toast("Position trouvée !"); }, (err) => { App.Utils.toast("Erreur GPS", "danger"); btn.innerText = oldText; btn.disabled = false; });
    },
    cancelOrder: id => {
        if(confirm("Voulez-vous vraiment annuler cette commande ?")) {
          fetch(API_URL,{method:'POST',body:JSON.stringify({action:"cancelOrder",token:App.State.user.authToken,data:{orderId:id}})}).then(r=>r.json()).then(r=>{
            if(r.status==='success'){ App.Utils.toast("Commande annulée"); App.Profile.fetchOrders(); bootstrap.Modal.getInstance($('orderDetailModal')).hide(); }
            else { App.Utils.toast(r.message || "Erreur d'annulation", "danger"); }
          });
        }
    },
    saveAddress: () => {
       const t = document.querySelector('input[name="addrType"]:checked').value, s = $('addr-street').value, gps = $('addr-gps').value;
       if(!s && !gps) return App.Utils.toast("Adresse ou GPS requis");

       // Optimistic UI Update
       const newAddr = { type: t, val: s, gps: gps };
       if(!App.State.addresses) App.State.addresses = [];
       // Remove old if exists (simple logic)
       App.State.addresses = App.State.addresses.filter(a => a.type !== t);
       App.State.addresses.push(newAddr);
       App.Profile.renderAddresses();

       bootstrap.Modal.getInstance($('addressModal')).hide();
       fetch(API_URL, {method:'POST', body:JSON.stringify({action: "updateAddress",data: {userId: App.State.user.id,authToken: App.State.user.authToken,type: t,addressJson: JSON.stringify(newAddr)}})});
    }
  },

  API: {
     fetchUserData: (silent) => {
         const u = App.State.user; if(!u) return;
         if(!silent) App.Utils.toast("Syncing...");
         fetch(`${API_URL}?action=getUserData&token=${u.authToken}`).then(r=>r.json()).then(res=>{
             if(res.status === 'success') {
                 if(res.cart && res.cart !== "[]") {
                     try {
                         const serverCart = JSON.parse(res.cart);
                         App.State.cart = serverCart.map(sc => {
                             const [baseId, variant] = String(sc.id).split('-');
                             const p = App.State.catalog.find(c => String(c.id) === String(baseId));
                             if(!p) return null;
                             return {
                                 ...p,
                                 cartId: sc.id, 
                                 qty: sc.qty,
                                 selectedVariant: variant || null,
                                 title: variant ? `${App.Utils.text(p.title)} (${variant})` : p.title
                             };
                         }).filter(Boolean);
                         App.Cart.save(); 
                         App.Cart.render();
                     } catch(e) { console.log("Sync parsing error"); }
                 }
                 // --- FIXED: Store AND Render addresses ---
                 if(res.addresses) {
                     App.State.addresses = res.addresses;
                     if(App.Profile.renderAddresses) App.Profile.renderAddresses();
                 }
             }
         });
     }
  },

  Boot: () => {
    window.addEventListener('scroll', () => { document.body.classList.toggle('is-scrolled', window.scrollY > 10); });
    App.Router.init();
    fetch(API_URL + "?action=getTranslations").then(r=>r.json()).then(r=>{ if(r.status==='success') { App.State.translations = r.translations; App.State.config = r.config || {}; } App.Catalog.init(); }).catch(e => { App.Catalog.init(); });
    setTimeout(() => { const l = document.getElementById('intro-loader'); if(l) l.style.display='none'; }, 1500);
    // Auto-login check
    try { const u=JSON.parse(localStorage.getItem('se_user')); if(u) App.Auth.restoreSession(u); } catch(e){}
    try{ const c=localStorage.getItem('se_cart'); if(c) App.State.cart=JSON.parse(c); const w=localStorage.getItem('se_wishlist'); if(w) App.State.wishlist=JSON.parse(w); App.Cart.render(); App.Wishlist.render(); } catch(e){}
  }
};
document.addEventListener('DOMContentLoaded', App.Boot);
//
